    return null;
}

var dayName = match[1]; // เช่น "ศุกร์"
var timeNow = match[2]; // เช่น "00:14:26"

// ตรวจสอบว่าวันนี้เปิดหรือไม่
var isDayAllowed = period.date.some(d => d[dayName] === true);

