}

// ตรวจสอบว่าช่วงเวลาไหนที่ตรง
let currentRange = period.time.find(range => {
    return range.start <= timeNow && timeNow <= range.to;
});

if (currentRange) {
    message = `✅ ตอนนี้ (${timeNow}) อยู่ในช่วง ${currentRange.start} ถึง ${currentRange.to}`;
    msg.payload = message
    msg.inRange = true;
    var remaining = getTimeRemaining(timeNow, currentRange.to);
    msg.text = `${currentRange.start}น. ถึง ${currentRange.to}น.<br>
    [${remaining.hours}ชั่วโมง ${remaining.minutes}นาที ${remaining.seconds}วินาที]`;
    node.status({ fill: "blue", shape: "dot", text: message });
} else {
    message = `❌ ตอนนี้ (${timeNow}) ไม่อยู่ในช่วงเวลาใด`;
    msg.payload = message;
    msg.inRange = false;
