let buttonState = global.get("Button_State") ?? {};
let selected = global.get("MW_Selected") ?? {};
let serial = global.get("serial") ?? "";

let displaySpeed = Math.abs(speed).toFixed(2);
let displayRotate = Math.abs(rotate).toFixed(2);

let speedValue = 0;
if (Number(displaySpeed) > 0) {
  speedValue = Number(displaySpeed);
} else if (Number(displayRotate) > 0) {
  speedValue = Number(displayRotate);
}

let robotStatus = { message: "-", textColor: "#000000" };

if (buttonState.button4) {
  robotStatus = {
    message: "Free Motor\nกรุณาปลดปุ่ม Free Motor",
    textColor: "#ff7500",
    textSize: "2em"
  };
} else {
  switch (status) {
    case 2:
      robotStatus = speed || rotate
        ? { message: "Moving", textColor: "#2192FF" }
        : { message: "Standby", textColor: "#663399" };
      break;
    case 5:
      robotStatus = { message: "Standby", textColor: "#663399" };
      break;
    case 11:
      robotStatus = {
        message: "Ready to start\nกรุณากดปุ่ม On program",
        textColor: "#feff63",
        textSize: "2em"
      };
      break;
    case 12:
      robotStatus = { message: "Auto Charging", textColor: "#cd5c08", textSize: "3em" };
      break;
    case 14:
      robotStatus = { message: "Device Error", textColor: "#ff1a00" };
      break;
    case 19:
      robotStatus = { message: "Cable Charging", textColor: "#EB5353", textSize: "3em" };
      break;
    case 23:
      robotStatus = { message: "Pause Robot", textColor: "#38E54D" };
      break;
    case 99:
      robotStatus = { message: "IDLE", textColor: "#ff1a00" };
      break;
  }
}

msg.payload = {
  Serial: serial,
  Destination: selected.building,
  Percent: Number(global.get("battery_mobile") ?? 0),
  Voltage: voltage.toFixed(2),
  Current: current.toFixed(2),
  Charge: current > 0 ? "Battery Charging." : "Not Charge.",
  Speed: speedValue,
  Moving: speedValue > 0 ? "Forward" : "Stop",
  "Status Robot": robotStatus
};

return msg;

